#include <bits/stdc++.h>
using namespace std;
static inline int F(int s){return s&7;} static inline int R(int s){return s>>3;} static inline int C(int s){return (F(s)+R(s))&1;} static inline int cheb(int a,int b){return max(abs(F(a)-F(b)),abs(R(a)-R(b)));}
vector<int> kingMv[64];
void initMoves(){for(int s=0;s<64;s++)for(int df=-1;df<=1;df++)for(int dr=-1;dr<=1;dr++)if(df||dr){int f=F(s)+df,r=R(s)+dr;if(f>=0&&f<8&&r>=0&&r<8)kingMv[s].push_back(r*8+f);}}
bool sliderAtt(char pt,int from,int to,const vector<int>&blocks){int df=F(to)-F(from),dr=R(to)-R(from),sf=0,sr=0;if(pt=='B'){if(df==0||abs(df)!=abs(dr))return false;sf=(df>0?1:-1);sr=(dr>0?1:-1);}else if(pt=='R'){if(df!=0&&dr!=0)return false;sf=(df>0)-(df<0);sr=(dr>0)-(dr<0);}else{if(df==0||dr==0){sf=(df>0)-(df<0);sr=(dr>0)-(dr<0);}else if(abs(df)==abs(dr)){sf=(df>0?1:-1);sr=(dr>0?1:-1);}else return false;}int f=F(from)+sf,r=R(from)+sr;while(f!=F(to)||r!=R(to)){int q=r*8+f;for(int b:blocks)if(q==b)return false;f+=sf;r+=sr;}return true;}
bool knightAtt(int from,int to){int df=abs(F(from)-F(to)),dr=abs(R(from)-R(to));return (df==1&&dr==2)||(df==2&&dr==1);}
bool pawnAttW(int p,int q){return R(q)-R(p)==1&&abs(F(q)-F(p))==1;}

// Post-promotion exact continuation classifier for lone black king, no 50-move rule.
// Existing bishops are all wrong-colour (C=1); promoted piece appears on h8 (C=0).
bool promotionChoiceWins(int wk,int bk,const vector<int>&bishops,char promo){int psq=63; // h8
  auto whiteAtt=[&](int q,bool promoPresent){if(cheb(wk,q)<=1)return true;vector<int> blocks=bishops;if(promoPresent)blocks.push_back(psq);for(int b:bishops)if(sliderAtt('B',b,q,blocks))return true;if(promoPresent){vector<int> pb=bishops;if(promo=='N'){if(knightAtt(psq,q))return true;}else if(sliderAtt(promo,psq,q,pb))return true;}return false;};
  bool capturePromo=false;int legal=0;for(int nb:kingMv[bk]){if(nb==wk)continue;if(nb==psq){ // capture promoted unit; test square after it disappears
      if(cheb(nb,wk)<=1)continue;bool att=false;vector<int> bl=bishops;for(int b:bishops)if(sliderAtt('B',b,nb,bl)){att=true;break;}if(att)continue;capturePromo=true;legal++;continue;}
    if(whiteAtt(nb,true))continue;legal++;}
  bool chk=whiteAtt(bk,true);if(legal==0)return chk; // checkmate win, stalemate draw
  if(capturePromo)return false; // Black chooses the draw by capture; remaining bishops alone cannot mate (all same colour).
  bool matingMaterial=(promo=='Q'||promo=='R'||(!bishops.empty()&&(promo=='B'||promo=='N')));return matingMaterial;
}
bool promotionWins(int wk,int bk,const vector<int>&bishops){for(char p: {'Q','R','B','N'})if(promotionChoiceWins(wk,bk,bishops,p))return true;return false;}

struct KPK{vector<uint8_t>valid,win;int W=0,D=0;};
static inline int kc(int pri,int wk,int bk,int t){return (((pri*64+wk)*64+bk)*2+t);}static inline void kd(int c,int&pri,int&wk,int&bk,int&t){t=c&1;int x=c>>1;bk=x%64;x/=64;wk=x%64;pri=x/64;}
KPK solveKPK(){const int SZ=6*64*64*2;KPK k;k.valid.assign(SZ,0);k.win.assign(SZ,0);for(int pri=0;pri<6;pri++){int p=(pri+1)*8+7;for(int wk=0;wk<64;wk++)if(wk!=p)for(int bk=0;bk<64;bk++)if(bk!=p&&bk!=wk&&cheb(wk,bk)>1){k.valid[kc(pri,wk,bk,1)]=1;if(!pawnAttW(p,bk))k.valid[kc(pri,wk,bk,0)]=1;}}
 vector<int>ss;auto succ=[&](int c,vector<int>&v,int&extW,int&extD,bool&check){v.clear();extW=extD=0;int pri,wk,bk,t;kd(c,pri,wk,bk,t);int p=(pri+1)*8+7;check=(t==1&&pawnAttW(p,bk));if(t==0){for(int nw:kingMv[wk])if(nw!=p&&nw!=bk&&cheb(nw,bk)>1){int d=kc(pri,nw,bk,1);if(k.valid[d])v.push_back(d);}int q=p+8;if(q<64&&q!=wk&&q!=bk){if(pri==5){if(promotionWins(wk,bk,{}))extW++;else extD++;}else{int d=kc(pri+1,wk,bk,1);if(k.valid[d])v.push_back(d);if(pri==0){int q2=p+16;if(q2!=wk&&q2!=bk){int e=kc(2,wk,bk,1);if(k.valid[e])v.push_back(e);}}}}}else{for(int nb:kingMv[bk]){if(nb==wk)continue;if(nb==p){if(cheb(nb,wk)>1)extD++;continue;}if(cheb(nb,wk)<=1||pawnAttW(p,nb))continue;int d=kc(pri,wk,nb,0);if(k.valid[d])v.push_back(d);}}};
 bool ch=true;int pass=0;while(ch&&pass++<100){ch=false;for(int c=0;c<SZ;c++)if(k.valid[c]&&!k.win[c]){int ew,ed;bool chk;succ(c,ss,ew,ed,chk);int pri,wk,bk,t;kd(c,pri,wk,bk,t);if(t==0){if(ew){k.win[c]=1;ch=true;continue;}for(int s:ss)if(k.win[s]){k.win[c]=1;ch=true;break;}}else{int total=ss.size()+ew+ed;if(total==0){if(chk){k.win[c]=1;ch=true;}}else if(ed==0){bool all=true;for(int s:ss)if(!k.win[s]){all=false;break;}if(all){k.win[c]=1;ch=true;}}}}}
 for(int c=0;c<SZ;c++)if(k.valid[c]){if(k.win[c])k.W++;else k.D++;}return k;}

vector<int> BS;int BI[64];
void initB(){fill(begin(BI),end(BI),-1);for(int s=0;s<64;s++)if(C(s)==1){BI[s]=BS.size();BS.push_back(s);}}

struct F4S{int pri,wk,b,bk,t;};
struct F4{
 const KPK&K; static const int SZ=6*64*32*64*2;vector<uint8_t>valid,win,rem;F4(const KPK&k):K(k){valid.assign(SZ,0);win.assign(SZ,0);rem.assign(SZ,0);}int code(F4S s)const{return ((((s.pri*64+s.wk)*32+BI[s.b])*64+s.bk)*2+s.t);}F4S dec(int c)const{F4S s;s.t=c&1;int x=c>>1;s.bk=x%64;x/=64;int bi=x%32;x/=32;s.wk=x%64;s.pri=x/64;s.b=BS[bi];return s;}int p(F4S s)const{return (s.pri+1)*8+7;}
 bool batt(F4S s,int q,int ignore=-1)const{vector<int>bl;int pp=p(s);if(pp!=ignore)bl.push_back(pp);if(s.wk!=ignore)bl.push_back(s.wk);return sliderAtt('B',s.b,q,bl);}
 bool validS(F4S s)const{int pp=p(s);if(s.wk==s.b||s.wk==s.bk||s.b==s.bk||pp==s.wk||pp==s.b||pp==s.bk||cheb(s.wk,s.bk)<=1)return false;if(s.t==0&&(pawnAttW(pp,s.bk)||batt(s,s.bk)))return false;return true;}
 bool check(F4S s)const{return s.t==1&&(pawnAttW(p(s),s.bk)||batt(s,s.bk));}
 void build(){long long n=0;for(int c=0;c<SZ;c++){auto s=dec(c);if(validS(s)){valid[c]=1;n++;}}cerr<<"F4 static="<<n<<"\n";}
 struct MS{vector<int>in;int ew=0,ed=0;};
 MS succ(F4S s)const{MS m;int pp=p(s);if(s.t==0){for(int nw:kingMv[s.wk])if(nw!=s.b&&nw!=pp&&nw!=s.bk&&cheb(nw,s.bk)>1){F4S z=s;z.wk=nw;z.t=1;if(validS(z))m.in.push_back(code(z));}int dirs[4][2]={{1,1},{1,-1},{-1,1},{-1,-1}};for(auto &d:dirs){int f=F(s.b)+d[0],r=R(s.b)+d[1];while(f>=0&&f<8&&r>=0&&r<8){int q=r*8+f;if(q==s.wk||q==pp||q==s.bk)break;F4S z=s;z.b=q;z.t=1;if(validS(z))m.in.push_back(code(z));f+=d[0];r+=d[1];}}int q=pp+8;if(q<64&&q!=s.wk&&q!=s.b&&q!=s.bk){if(s.pri==5){if(promotionWins(s.wk,s.bk,{s.b}))m.ew++;else m.ed++;}else{F4S z=s;z.pri++;z.t=1;if(validS(z))m.in.push_back(code(z));if(s.pri==0){int q2=pp+16;if(q2!=s.wk&&q2!=s.b&&q2!=s.bk){z=s;z.pri=2;z.t=1;if(validS(z))m.in.push_back(code(z));}}}}}else{for(int nb:kingMv[s.bk]){if(nb==s.wk)continue;if(nb==pp){if(cheb(nb,s.wk)>1&&!batt(s,nb)){m.ed++;}continue;}if(nb==s.b){if(cheb(nb,s.wk)>1&&!pawnAttW(pp,nb)){int kk=kc(s.pri,s.wk,nb,0);if(K.valid[kk]&&K.win[kk])m.ew++;else m.ed++;}continue;}if(cheb(nb,s.wk)<=1||pawnAttW(pp,nb)||batt(s,nb))continue;F4S z=s;z.bk=nb;z.t=0;if(validS(z))m.in.push_back(code(z));}}return m;}
 template<class FN>void preds(int cc,FN fn)const{F4S s=dec(cc);bool pw=s.t==1;auto test=[&](F4S z){z.t=pw?0:1;if(!validS(z))return;int pc=code(z);if(!valid[pc])return;auto m=succ(z);if(find(m.in.begin(),m.in.end(),cc)!=m.in.end())fn(pc);};if(pw){for(int o:kingMv[s.wk]){F4S z=s;z.wk=o;test(z);}int dirs[4][2]={{1,1},{1,-1},{-1,1},{-1,-1}};for(auto &d:dirs){int f=F(s.b)+d[0],r=R(s.b)+d[1];while(f>=0&&f<8&&r>=0&&r<8){int o=r*8+f;if(o==s.wk||o==s.bk||o==p(s))break;F4S z=s;z.b=o;test(z);f+=d[0];r+=d[1];}}if(s.pri>0){F4S z=s;z.pri--;test(z);}if(s.pri==2){F4S z=s;z.pri=0;test(z);}}else for(int o:kingMv[s.bk]){F4S z=s;z.bk=o;test(z);}}
 void targetAudit(){if(valid.empty()||count(valid.begin(),valid.end(),1)==0)solve();vector<uint8_t>att(SZ,0),rr(SZ,0);deque<int>q;long long direct=0,directBad=0;for(int c=0;c<SZ;c++)if(valid[c]){auto s=dec(c);bool tg=s.pri>=4&&cheb(s.wk,63)<=4&&cheb(s.bk,63)>=5;if(tg){direct++;if(!win[c])directBad++;att[c]=1;q.push_back(c);}}for(int c=0;c<SZ;c++)if(valid[c]&&!att[c]){auto s=dec(c);if(s.t!=1)continue;auto m=succ(s);int total=m.in.size()+m.ew+m.ed;rr[c]=uint8_t(min(255,total?total:1));}while(!q.empty()){int c=q.front();q.pop_front();preds(c,[&](int p){if(att[p])return;auto s=dec(p);if(s.t==0){att[p]=1;q.push_back(p);}else if(rr[p]>0&&--rr[p]==0){att[p]=1;q.push_back(p);}});}long long n=0,bad=0;for(int c=0;c<SZ;c++)if(valid[c]&&att[c]){n++;if(!win[c])bad++;}cout<<"F4_TARGET_AUDIT direct="<<direct<<" direct_bad="<<directBad<<" strict_attr="<<n<<" attr_bad="<<bad<<"\n";}
 void solve(){build();deque<int>q;for(int c=0;c<SZ;c++)if(valid[c]){auto s=dec(c);auto m=succ(s);if(s.t==0){if(m.ew){win[c]=1;q.push_back(c);}}else{int non=m.in.size()+m.ed;rem[c]=min(255,non);int total=m.in.size()+m.ed+m.ew;if(total==0&&check(s)){win[c]=1;q.push_back(c);}else if(total>0&&non==0){win[c]=1;q.push_back(c);}}}while(!q.empty()){int c=q.front();q.pop_front();preds(c,[&](int p){if(win[p])return;auto s=dec(p);if(s.t==0){win[p]=1;q.push_back(p);}else if(rem[p]>0){if(--rem[p]==0){win[p]=1;q.push_back(p);}}});}long long W=0,D=0,bkh8=0,bkh8W=0;for(int c=0;c<SZ;c++)if(valid[c]){if(win[c])W++;else D++;auto s=dec(c);if(s.bk==63){bkh8++;if(win[c])bkh8W++;}}cout<<"F4_RESULT static="<<W+D<<" W="<<W<<" D="<<D<<" BK_h8="<<bkh8<<" BK_h8_W="<<bkh8W<<"\n";ofstream fv("/mnt/data/G7_4_F4_valid.bin",ios::binary);fv.write((char*)valid.data(),valid.size());ofstream fw("/mnt/data/G7_4_F4_win.bin",ios::binary);fw.write((char*)win.data(),win.size());}
};

// Two identical wrong-colour bishops: canonical unordered pair, full-material stratum only; captures exit to exact F4.
struct Pair{int a,b;};vector<Pair> PAIRS;int PIND[64][64];
void initPairs(){for(auto &r:PIND)fill(begin(r),end(r),-1);for(int i=0;i<32;i++)for(int j=i+1;j<32;j++){int id=PAIRS.size();PAIRS.push_back({BS[i],BS[j]});PIND[BS[i]][BS[j]]=PIND[BS[j]][BS[i]]=id;}}
struct F5S{int pri,wk,pair,bk,t;};
struct F5{const KPK&K;const F4&L;int NP=496;uint64_t SZ;vector<uint8_t>valid,win,rem;F5(const KPK&k,const F4&l):K(k),L(l){SZ=uint64_t(6)*64*NP*64*2;valid.assign(SZ,0);win.assign(SZ,0);rem.assign(SZ,0);}uint64_t code(F5S s)const{uint64_t x=s.pri;x=x*64+s.wk;x=x*NP+s.pair;x=x*64+s.bk;x=x*2+s.t;return x;}F5S dec(uint64_t c)const{F5S s;s.t=c&1;c>>=1;s.bk=c%64;c/=64;s.pair=c%NP;c/=NP;s.wk=c%64;c/=64;s.pri=c;return s;}int p(F5S s)const{return (s.pri+1)*8+7;}vector<int>bs(F5S s)const{return {PAIRS[s.pair].a,PAIRS[s.pair].b};}
 bool batt(F5S s,int q,int moving=-1,int newpos=-1)const{auto b=bs(s);vector<int>blocks={p(s),s.wk};for(int x:b)if(x!=moving)blocks.push_back(x);if(newpos>=0)blocks.push_back(newpos);for(int x:b)if(x!=moving&&sliderAtt('B',x,q,blocks))return true;if(moving>=0&&newpos>=0){vector<int>bl={p(s),s.wk};for(int x:b)if(x!=moving)bl.push_back(x);if(sliderAtt('B',newpos,q,bl))return true;}return false;}
 bool validS(F5S s)const{auto b=bs(s);int pp=p(s);int a=b[0],d=b[1];if(s.wk==s.bk||cheb(s.wk,s.bk)<=1)return false;int v[5]={s.wk,s.bk,a,d,pp};for(int i=0;i<5;i++)for(int j=i+1;j<5;j++)if(v[i]==v[j])return false;if(s.t==0&&(pawnAttW(pp,s.bk)||batt(s,s.bk)))return false;return true;}
 bool check(F5S s)const{return s.t==1&&(pawnAttW(p(s),s.bk)||batt(s,s.bk));}
 void build(){uint64_t n=0;for(uint64_t c=0;c<SZ;c++)if(validS(dec(c))){valid[c]=1;n++;}cerr<<"F5 raw="<<SZ<<" static="<<n<<"\n";}
 struct MS{vector<uint64_t>in;int ew=0,ed=0;};
 MS succ(F5S s)const{MS m;auto b=bs(s);int pp=p(s);if(s.t==0){for(int nw:kingMv[s.wk])if(nw!=b[0]&&nw!=b[1]&&nw!=pp&&nw!=s.bk&&cheb(nw,s.bk)>1){F5S z=s;z.wk=nw;z.t=1;if(validS(z))m.in.push_back(code(z));}for(int which=0;which<2;which++){int from=b[which],other=b[1-which];int dirs[4][2]={{1,1},{1,-1},{-1,1},{-1,-1}};for(auto &di:dirs){int f=F(from)+di[0],r=R(from)+di[1];while(f>=0&&f<8&&r>=0&&r<8){int q=r*8+f;if(q==s.wk||q==s.bk||q==pp||q==other)break;int i1=BI[q],i2=BI[other];if(i1>=0&&i2>=0&&q!=other){F5S z=s;z.pair=PIND[q][other];z.t=1;if(z.pair>=0&&validS(z))m.in.push_back(code(z));}f+=di[0];r+=di[1];}}}int q=pp+8;if(q<64&&q!=s.wk&&q!=s.bk&&q!=b[0]&&q!=b[1]){if(s.pri==5){if(promotionWins(s.wk,s.bk,b))m.ew++;else m.ed++;}else{F5S z=s;z.pri++;z.t=1;if(validS(z))m.in.push_back(code(z));if(s.pri==0){int q2=pp+16;if(q2!=s.wk&&q2!=s.bk&&q2!=b[0]&&q2!=b[1]){z=s;z.pri=2;z.t=1;if(validS(z))m.in.push_back(code(z));}}}}}else{for(int nb:kingMv[s.bk]){if(nb==s.wk)continue;if(nb==pp){if(cheb(nb,s.wk)>1&&!batt(s,nb))m.ed++;continue;}int cap=-1;if(nb==b[0])cap=0;if(nb==b[1])cap=1;if(cap>=0){int other=b[1-cap];if(cheb(nb,s.wk)<=1||pawnAttW(pp,nb))continue; // after capture, other bishop may protect capture square
        vector<int> bl={pp,s.wk};if(sliderAtt('B',other,nb,bl))continue;F4S lo{s.pri,s.wk,other,nb,0};if(L.validS(lo)&&L.win[L.code(lo)])m.ew++;else m.ed++;continue;}if(cheb(nb,s.wk)<=1||pawnAttW(pp,nb)||batt(s,nb))continue;F5S z=s;z.bk=nb;z.t=0;if(validS(z))m.in.push_back(code(z));}}return m;}
 template<class FN>void preds(uint64_t cc,FN fn)const{F5S s=dec(cc);bool pw=s.t==1;auto test=[&](F5S z){z.t=pw?0:1;if(!validS(z))return;uint64_t pc=code(z);if(!valid[pc])return;fn(pc);};if(pw){for(int o:kingMv[s.wk]){F5S z=s;z.wk=o;test(z);}auto b=bs(s);for(int which=0;which<2;which++){int dest=b[which],other=b[1-which];int dirs[4][2]={{1,1},{1,-1},{-1,1},{-1,-1}};for(auto &di:dirs){int f=F(dest)+di[0],r=R(dest)+di[1];while(f>=0&&f<8&&r>=0&&r<8){int o=r*8+f;if(o==s.wk||o==s.bk||o==p(s)||o==other)break;if(BI[o]>=0){int pi=PIND[o][other];if(pi>=0){F5S z=s;z.pair=pi;test(z);}}f+=di[0];r+=di[1];}}}if(s.pri>0){F5S z=s;z.pri--;test(z);}if(s.pri==2){int mid=23;auto bb=bs(s);if(s.wk!=mid&&s.bk!=mid&&bb[0]!=mid&&bb[1]!=mid){F5S z=s;z.pri=0;test(z);}}}else for(int o:kingMv[s.bk]){F5S z=s;z.bk=o;test(z);}}
 void predaudit(){build();mt19937_64 rng(0xF57AULL);uint64_t snd=0,bad=0,comp=0,miss=0;int got=0;while(got<10000){uint64_t c=rng()%SZ;if(!valid[c])continue;got++;vector<uint64_t>ps;preds(c,[&](uint64_t p){ps.push_back(p);});for(auto p:ps){snd++;auto m=succ(dec(p));if(find(m.in.begin(),m.in.end(),c)==m.in.end())bad++;}auto m=succ(dec(c));for(auto x:m.in){comp++;bool ok=false;preds(x,[&](uint64_t p){if(p==c)ok=true;});if(!ok)miss++;}}cout<<"F5_PREDAUDIT sound="<<snd<<" bad="<<bad<<" forward="<<comp<<" missing="<<miss<<"\n";}
 template<class FN>void predsUnique(uint64_t cc,FN fn)const{vector<uint64_t>v;v.reserve(32);preds(cc,[&](uint64_t p){v.push_back(p);});sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());for(auto p:v)fn(p);}
 void loadMasks(){valid.assign(SZ,0);win.assign(SZ,0);ifstream fv("/mnt/data/G7_4_F5_valid.bin",ios::binary),fw("/mnt/data/G7_4_F5_win.bin",ios::binary);if(!fv||!fw){cerr<<"missing F5 masks\n";exit(3);}fv.read((char*)valid.data(),valid.size());fw.read((char*)win.data(),win.size());}
 bool targetSafe(F5S s)const{return R(p(s))>=5&&cheb(s.wk,63)<=4&&cheb(s.bk,63)>=5;}
 void targetAttractor(){loadMasks();vector<uint8_t>att(SZ,0),rr(SZ,0);deque<uint64_t>q;uint64_t direct=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]&&targetSafe(dec(c))){att[c]=1;q.push_back(c);direct++;}for(uint64_t c=0;c<SZ;c++)if(valid[c]&&!att[c]){auto s=dec(c);if(s.t!=1)continue;auto m=succ(s);sort(m.in.begin(),m.in.end());m.in.erase(unique(m.in.begin(),m.in.end()),m.in.end());uint64_t total=m.in.size()+((m.ew||m.ed)?1:0);rr[c]=uint8_t(min<uint64_t>(255,total?total:1));}while(!q.empty()){auto c=q.front();q.pop_front();predsUnique(c,[&](uint64_t p){if(att[p])return;auto s=dec(p);if(s.t==0){att[p]=1;q.push_back(p);}else if(rr[p]>0&&--rr[p]==0){att[p]=1;q.push_back(p);}});}uint64_t n=0,bad=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]&&att[c]){n++;if(!win[c])bad++;}cout<<"F5_TARGET_ATTR direct="<<direct<<" strict_attr="<<n<<" nonwin="<<bad<<"\n";ofstream fa("/mnt/data/G7_4_F5_target_attr.bin",ios::binary);fa.write((char*)att.data(),att.size());}
 void sanctuaryStrict(){loadMasks();vector<uint8_t>att(SZ,0),rr(SZ,0);deque<uint64_t>q;uint64_t direct=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]&&dec(c).bk==63){att[c]=1;q.push_back(c);direct++;}for(uint64_t c=0;c<SZ;c++)if(valid[c]&&!att[c]){auto s=dec(c);if(s.t!=0)continue;auto m=succ(s);sort(m.in.begin(),m.in.end());m.in.erase(unique(m.in.begin(),m.in.end()),m.in.end());uint64_t ext=(m.ew||m.ed)?1:0;uint64_t total=m.in.size()+ext;rr[c]=uint8_t(min<uint64_t>(255,total?total:1));}while(!q.empty()){auto c=q.front();q.pop_front();predsUnique(c,[&](uint64_t p){if(att[p])return;auto s=dec(p);if(s.t==1){att[p]=1;q.push_back(p);}else if(rr[p]>0&&--rr[p]==0){att[p]=1;q.push_back(p);}});}uint64_t n=0,falseW=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]&&att[c]){n++;if(win[c])falseW++;}cout<<"F5_SANCTUARY_STRICT direct="<<direct<<" strict_attr="<<n<<" falseW="<<falseW<<" exact_draw_basin=4442101 coverage_pct="<<fixed<<setprecision(4)<<(100.0*n/4442101.0)<<"\n";ofstream fa("/mnt/data/G7_4_F5_sanctuary_strict.bin",ios::binary);fa.write((char*)att.data(),att.size());}
 void sanctuaryAttractor(){loadMasks();vector<uint8_t>att(SZ,0),rr(SZ,0);deque<uint64_t>q;uint64_t direct=0,exitSeed=0,staleSeed=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]){auto s=dec(c);if(s.bk==63){att[c]=1;q.push_back(c);direct++;}}for(uint64_t c=0;c<SZ;c++)if(valid[c]&&!att[c]){auto s=dec(c);auto m=succ(s);sort(m.in.begin(),m.in.end());m.in.erase(unique(m.in.begin(),m.in.end()),m.in.end());uint64_t total=m.in.size()+((m.ew||m.ed)?1:0);if(s.t==1){if(m.ed>0){att[c]=1;q.push_back(c);exitSeed++;}else if(total==0&&!check(s)){att[c]=1;q.push_back(c);staleSeed++;}}else{if(total==0){att[c]=1;q.push_back(c);staleSeed++;}else{uint64_t fail=m.in.size()+(m.ew?1:0);rr[c]=uint8_t(min<uint64_t>(255,fail));if(fail==0){att[c]=1;q.push_back(c);exitSeed++;}}}}while(!q.empty()){auto c=q.front();q.pop_front();predsUnique(c,[&](uint64_t p){if(att[p])return;auto s=dec(p);if(s.t==1){att[p]=1;q.push_back(p);}else if(rr[p]>0&&--rr[p]==0){att[p]=1;q.push_back(p);}});}uint64_t n=0,draw=0,falseW=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]&&att[c]){n++;if(win[c])falseW++;else draw++;}cout<<"F5_SANCTUARY_ATTR direct="<<direct<<" exit_seed="<<exitSeed<<" stalemate_seed="<<staleSeed<<" attr="<<n<<" certified_draw="<<draw<<" falseW="<<falseW<<" exact_draw_basin=4442101 coverage_pct="<<fixed<<setprecision(4)<<(100.0*draw/4442101.0)<<"\n";ofstream fa("/mnt/data/G7_4_F5_sanctuary_attr.bin",ios::binary);fa.write((char*)att.data(),att.size());}
 void solve(){auto t0=chrono::steady_clock::now();build();deque<uint64_t>q;for(uint64_t c=0;c<SZ;c++)if(valid[c]){auto s=dec(c);auto m=succ(s);sort(m.in.begin(),m.in.end());m.in.erase(unique(m.in.begin(),m.in.end()),m.in.end());if(s.t==0){if(m.ew){win[c]=1;q.push_back(c);}}else{uint64_t non=m.in.size()+(m.ed?1:0);rem[c]=uint8_t(min<uint64_t>(255,non));uint64_t total=m.in.size()+((m.ed||m.ew)?1:0);if(total==0&&check(s)){win[c]=1;q.push_back(c);}else if(total>0&&non==0){win[c]=1;q.push_back(c);}}}cerr<<"F5 seeds="<<q.size()<<"\n";uint64_t pops=0;while(!q.empty()){uint64_t c=q.front();q.pop_front();predsUnique(c,[&](uint64_t p){if(win[p])return;auto s=dec(p);if(s.t==0){win[p]=1;q.push_back(p);}else if(rem[p]>0&&--rem[p]==0){win[p]=1;q.push_back(p);}});if(++pops%1000000==0)cerr<<"F5 pops="<<pops<<" q="<<q.size()<<"\n";}uint64_t W=0,D=0,h=0,hw=0,target=0,targetBad=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]){auto s=dec(c);if(win[c])W++;else D++;if(s.bk==63){h++;if(win[c])hw++;}int pp=p(s);bool tg=R(pp)>=5&&cheb(s.wk,63)<=4&&cheb(s.bk,63)>=5;if(tg){target++;if(!win[c])targetBad++;}}uint64_t bc=0,bad=0;for(uint64_t c=0;c<SZ;c++)if(valid[c]&&c%257==0){bc++;auto s=dec(c);auto m=succ(s);bool exp=false;if(s.t==0){if(m.ew)exp=true;else for(auto x:m.in)if(win[x]){exp=true;break;}}else{uint64_t total=m.in.size()+m.ew+m.ed;if(total==0)exp=check(s);else if(m.ed==0){exp=true;for(auto x:m.in)if(!win[x]){exp=false;break;}}}if(exp!=(bool)win[c])bad++;}double sec=chrono::duration<double>(chrono::steady_clock::now()-t0).count();cout<<"F5_RESULT static="<<W+D<<" W="<<W<<" D="<<D<<" BK_h8="<<h<<" BK_h8_W="<<hw<<" TARGET_SAFE_like="<<target<<" target_draw_fail="<<targetBad<<" bellman_checked="<<bc<<" bellman_bad="<<bad<<" sec="<<fixed<<setprecision(3)<<sec<<"\n";ofstream fv("/mnt/data/G7_4_F5_valid.bin",ios::binary);fv.write((char*)valid.data(),valid.size());ofstream fw("/mnt/data/G7_4_F5_win.bin",ios::binary);fw.write((char*)win.data(),win.size());}
};
int main(int argc,char**argv){ios::sync_with_stdio(false);cin.tie(nullptr);initMoves();initB();initPairs();string mode=argc>1?argv[1]:"baseline";auto K=solveKPK();cout<<"KPK static="<<K.W+K.D<<" W="<<K.W<<" D="<<K.D<<"\n";F4 f4(K);if(mode=="baseline"||mode=="f5"||mode=="audit"||mode=="target"||mode=="sanctuary"||mode=="sanctuaryStrict"){f4.solve();}if(mode=="audit"){F5 f5(K,f4);f5.predaudit();}if(mode=="f5"){F5 f5(K,f4);f5.solve();}if(mode=="target"){F5 f5(K,f4);f5.targetAttractor();}if(mode=="sanctuary"){F5 f5(K,f4);f5.sanctuaryAttractor();}if(mode=="sanctuaryStrict"){F5 f5(K,f4);f5.sanctuaryStrict();}if(mode=="f4target"){f4.solve();f4.targetAudit();}return 0;}
